// Demonstrating method definition and calling
public class MethodsDemo {

    // Method without parameters and return value
    public static void greetUser() {
        System.out.println("Hello! Welcome to our program!");
        System.out.println("We're glad to have you here!");
    }

    // Method with parameters but no return value
    public static void displayMessage(String message, int times) {
        for (int i = 0; i < times; i++) {
            System.out.println((i + 1) + ". " + message);
        }
    }

    // Method with parameters and return value
    public static int calculateSquare(int number) {
        int square = number * number;
        return square;  // Return the result
    }

    // Method with multiple parameters and return value
    public static double calculateRectangleArea(double length, double width) {
        return length * width;
    }

    // Method that calls other methods
    public static void printSquareInfo(int num) {
        int result = calculateSquare(num);
        System.out.println("The square of " + num + " is: " + result);
    }

    // Method with conditional logic
    public static String checkNumber(int number) {
        if (number > 0) {
            return "Positive";
        } else if (number < 0) {
            return "Negative";
        } else {
            return "Zero";
        }
    }

    // Main method - program entry point
    public static void main(String[] args) {
        System.out.println("=== Method Demonstration ===\n");

        // Calling method without parameters
        greetUser();

        System.out.println("\n--- Calling methods with parameters ---");

        // Calling method with parameters
        displayMessage("Java is fun!", 3);

        // Calling method that returns a value
        int num = 5;
        int squared = calculateSquare(num);
        System.out.println("\nSquare of " + num + " is: " + squared);

        // Using returned value directly
        System.out.println("Square of 8 is: " + calculateSquare(8));

        // Calling method with multiple parameters
        double area = calculateRectangleArea(5.5, 3.2);
        System.out.println("Rectangle area: " + area);

        System.out.println("\n--- Method chaining ---");

        // Calling method that calls other methods
        printSquareInfo(7);

        System.out.println("\n--- Methods with conditional logic ---");

        // Using method with conditional return
        System.out.println("10 is: " + checkNumber(10));
        System.out.println("-5 is: " + checkNumber(-5));
        System.out.println("0 is: " + checkNumber(0));

        // Practical example: Calculator methods
        System.out.println("\n--- Calculator Example ---");

        int a = 15, b = 4;
        System.out.println(a + " + " + b + " = " + add(a, b));
        System.out.println(a + " - " + b + " = " + subtract(a, b));
        System.out.println(a + " * " + b + " = " + multiply(a, b));
        System.out.println(a + " / " + b + " = " + divide(a, b));
    }

    // Additional calculator methods
    public static int add(int x, int y) {
        return x + y;
    }

    public static int subtract(int x, int y) {
        return x - y;
    }

    public static int multiply(int x, int y) {
        return x * y;
    }

    public static double divide(int x, int y) {
        if (y == 0) {
            System.out.println("Error: Division by zero!");
            return 0;
        }
        return (double) x / y;
    }
}

// Demonstrating parameters and return values
public class ParametersReturnDemo {

    // Method with multiple parameters and return value
    public static double calculateCircleArea(double radius) {
        return Math.PI * radius * radius;
    }

    // Method with multiple parameters
    public static String createFullName(String firstName, String lastName, String middleName) {
        if (middleName == null || middleName.isEmpty()) {
            return firstName + " " + lastName;
        } else {
            return firstName + " " + middleName + " " + lastName;
        }
    }

    // Method that returns boolean
    public static boolean isEven(int number) {
        return number % 2 == 0;
    }

    // Method that returns array
    public static int[] generateNumbers(int start, int end, int step) {
        int size = (end - start) / step + 1;
        int[] numbers = new int[size];

        for (int i = 0; i < size; i++) {
            numbers[i] = start + (i * step);
        }

        return numbers;
    }

    // Method with default parameter simulation (using overloading)
    public static double calculateDiscount(double price) {
        return calculateDiscount(price, 10.0); // Default 10% discount
    }

    public static double calculateDiscount(double price, double discountPercent) {
        return price * (1 - discountPercent / 100);
    }

    // Method that modifies parameters (primitive vs reference)
    public static void modifyValues(int primitiveParam, int[] referenceParam) {
        primitiveParam = 100; // This won't affect original
        if (referenceParam.length > 0) {
            referenceParam[0] = 999; // This will affect original array
        }
    }

    // Method with variable arguments (varargs)
    public static double findAverage(int... numbers) {
        if (numbers.length == 0) {
            return 0.0;
        }

        int sum = 0;
        for (int num : numbers) {
            sum += num;
        }

        return (double) sum / numbers.length;
    }

    // Method that returns multiple values using array
    public static double[] calculateCircleProperties(double radius) {
        double area = Math.PI * radius * radius;
        double circumference = 2 * Math.PI * radius;
        double diameter = 2 * radius;

        return new double[]{area, circumference, diameter};
    }

    public static void main(String[] args) {
        System.out.println("=== Parameters and Return Values ===\n");

        // Using method with return value
        double area = calculateCircleArea(5.0);
        System.out.println("Circle area with radius 5: " + area);

        // Using method with multiple parameters
        String fullName1 = createFullName("John", "Doe", "Michael");
        String fullName2 = createFullName("Jane", "Smith", null);
        System.out.println("Full name 1: " + fullName1);
        System.out.println("Full name 2: " + fullName2);

        // Using boolean return method
        System.out.println("\nEven number check:");
        System.out.println("Is 10 even? " + isEven(10));
        System.out.println("Is 7 even? " + isEven(7));

        // Using method that returns array
        int[] numberSequence = generateNumbers(0, 20, 5);
        System.out.println("\nGenerated numbers: ");
        for (int num : numberSequence) {
            System.out.print(num + " ");
        }
        System.out.println();

        // Using overloaded methods (default parameter simulation)
        System.out.println("\nDiscount calculations:");
        System.out.println("Price $100 with default discount: $" + calculateDiscount(100.0));
        System.out.println("Price $100 with 25% discount: $" + calculateDiscount(100.0, 25.0));

        // Demonstrating parameter passing
        System.out.println("\nParameter passing demonstration:");
        int primitiveValue = 50;
        int[] referenceValue = {1, 2, 3};

        System.out.println("Before modification:");
        System.out.println("primitiveValue: " + primitiveValue);
        System.out.println("referenceValue[0]: " + referenceValue[0]);

        modifyValues(primitiveValue, referenceValue);

        System.out.println("After modification:");
        System.out.println("primitiveValue: " + primitiveValue + " (unchanged - primitive)");
        System.out.println("referenceValue[0]: " + referenceValue[0] + " (changed - reference)");

        // Using varargs
        System.out.println("\nAverage calculations:");
        System.out.println("Average of 10, 20, 30: " + findAverage(10, 20, 30));
        System.out.println("Average of 5, 15, 25, 35, 45: " + findAverage(5, 15, 25, 35, 45));
        System.out.println("Average of no numbers: " + findAverage());

        // Using method that returns multiple values
        System.out.println("\nCircle properties for radius 7:");
        double[] properties = calculateCircleProperties(7.0);
        System.out.println("Area: " + properties[0]);
        System.out.println("Circumference: " + properties[1]);
        System.out.println("Diameter: " + properties[2]);

        // Practical example: Student grade calculator
        System.out.println("\n=== Student Grade Calculator ===");
        double[] grades = {85.5, 92.0, 78.5, 88.0, 95.5};
        double averageGrade = calculateAverage(grades);
        String letterGrade = convertToLetterGrade(averageGrade);

        System.out.println("Grades: ");
        for (double grade : grades) {
            System.out.print(grade + " ");
        }
        System.out.println("\nAverage: " + averageGrade);
        System.out.println("Letter Grade: " + letterGrade);
    }

    // Helper methods for grade calculator
    public static double calculateAverage(double[] grades) {
        if (grades.length == 0) return 0.0;

        double sum = 0;
        for (double grade : grades) {
            sum += grade;
        }
        return sum / grades.length;
    }

    public static String convertToLetterGrade(double average) {
        if (average >= 90) return "A";
        else if (average >= 80) return "B";
        else if (average >= 70) return "C";
        else if (average >= 60) return "D";
        else return "F";
    }
}

// Demonstrating arrays in Java
public class ArraysDemo {
    public static void main(String[] args) {
        System.out.println("=== Arrays Demonstration ===\n");

        // Array declaration and initialization
        int[] numbers = new int[5];  // Array of 5 integers

        // Assigning values to array elements
        numbers[0] = 10;  // First element (index 0)
        numbers[1] = 20;  // Second element (index 1)
        numbers[2] = 30;
        numbers[3] = 40;
        numbers[4] = 50;  // Last element (index 4)

        // Alternative initialization
        int[] scores = {85, 92, 78, 90, 88};  // Declare and initialize

        // Accessing array elements
        System.out.println("First number: " + numbers[0]);
        System.out.println("Third score: " + scores[2]);

        // Array length
        System.out.println("\nArray lengths:");
        System.out.println("Numbers array length: " + numbers.length);
        System.out.println("Scores array length: " + scores.length);

        // Looping through arrays
        System.out.println("\nNumbers array:");
        for (int i = 0; i < numbers.length; i++) {
            System.out.println("Index " + i + ": " + numbers[i]);
        }

        // Enhanced for loop (for-each)
        System.out.println("\nScores array (for-each):");
        for (int score : scores) {
            System.out.println("Score: " + score);
        }

        // String array
        String[] fruits = {"Apple", "Banana", "Orange", "Grape", "Mango"};

        System.out.println("\nFruits:");
        for (String fruit : fruits) {
