// Demonstrating multi-dimensional arrays
public class MultiDimensionalArraysDemo {
    public static void main(String[] args) {
        System.out.println("=== Multi-Dimensional Arrays ===\n");

        // 2D array declaration and initialization
        int[][] matrix = new int[3][4];  // 3 rows, 4 columns

        // Assigning values to 2D array
        matrix[0][0] = 1;  // Row 0, Column 0
        matrix[0][1] = 2;
        matrix[0][2] = 3;
        matrix[0][3] = 4;

        matrix[1][0] = 5;  // Row 1, Column 0
        matrix[1][1] = 6;
        matrix[1][2] = 7;
        matrix[1][3] = 8;

        matrix[2][0] = 9;  // Row 2, Column 0
        matrix[2][1] = 10;
        matrix[2][2] = 11;
        matrix[2][3] = 12;

        // Alternative initialization
        int[][] predefinedMatrix = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };

        // Displaying 2D arrays
        System.out.println("3x4 Matrix:");
        print2DArray(matrix);

        System.out.println("\n3x3 Predefined Matrix:");
        print2DArray(predefinedMatrix);

        // Accessing elements
        System.out.println("\nElement at [1][2]: " + matrix[1][2]);
        System.out.println("Element at [2][1]: " + predefinedMatrix[2][1]);

        // Array dimensions
        System.out.println("\nMatrix dimensions:");
        System.out.println("Rows: " + matrix.length);
        System.out.println("Columns in row 0: " + matrix[0].length);

        // Jagged arrays (arrays with different row lengths)
        System.out.println("\n=== Jagged Arrays ===");

        int[][] jaggedArray = new int[3][];  // 3 rows, unknown columns
        jaggedArray[0] = new int[2];  // Row 0 has 2 columns
        jaggedArray[1] = new int[4];  // Row 1 has 4 columns
        jaggedArray[2] = new int[3];  // Row 2 has 3 columns

        // Initialize jagged array
        int value = 1;
        for (int i = 0; i < jaggedArray.length; i++) {
            for (int j = 0; j < jaggedArray[i].length; j++) {
                jaggedArray[i][j] = value++;
            }
        }

        System.out.println("Jagged Array:");
        printJaggedArray(jaggedArray);

        // 3D arrays
        System.out.println("\n=== 3D Arrays ===");

        int[][][] threeDArray = new int[2][3][4];  // 2 layers, 3 rows, 4 columns

        // Initialize 3D array
        int counter = 1;
        for (int i = 0; i < threeDArray.length; i++) {
            for (int j = 0; j < threeDArray[i].length; j++) {
                for (int k = 0; k < threeDArray[i][j].length; k++) {
                    threeDArray[i][j][k] = counter++;
                }
            }
        }

        System.out.println("3D Array (first layer):");
        print2DArray(threeDArray[0]);

        System.out.println("\n3D Array (second layer):");
        print2DArray(threeDArray[1]);

        // Practical examples
        System.out.println("\n=== Practical Examples ===");

        // Student grades table
        String[] students = {"Alice", "Bob", "Charlie"};
        String[] subjects = {"Math", "Science", "English"};
        int[][] grades = {
            {85, 92, 78},  // Alice's grades
            {76, 88, 90},  // Bob's grades
            {92, 95, 87}   // Charlie's grades
        };

        System.out.println("Student Grade Report:");
        System.out.print("Student\t\t");
        for (String subject : subjects) {
            System.out.print(subject + "\t");
        }
        System.out.println("Average");

        for (int i = 0; i < students.length; i++) {
            System.out.print(students[i] + "\t\t");
            int sum = 0;
            for (int j = 0; j < subjects.length; j++) {
                System.out.print(grades[i][j] + "\t\t");
                sum += grades[i][j];
            }
            double average = (double) sum / subjects.length;
            System.out.printf("%.2f\n", average);
        }

        // Matrix operations
        System.out.println("\n=== Matrix Operations ===");

        int[][] matrixA = {{1, 2, 3}, {4, 5, 6}};
        int[][] matrixB = {{7, 8, 9}, {10, 11, 12}};

        System.out.println("Matrix A:");
        print2DArray(matrixA);

        System.out.println("Matrix B:");
        print2DArray(matrixB);

        System.out.println("Matrix A + B:");
        int[][] sumMatrix = addMatrices(matrixA, matrixB);
        print2DArray(sumMatrix);

        // Transpose of matrix
        System.out.println("Transpose of Matrix A:");
        int[][] transposeA = transposeMatrix(matrixA);
        print2DArray(transposeA);
    }

    // Method to print 2D array
    public static void print2DArray(int[][] arr) {
        for (int i = 0; i < arr.length; i++) {
            for (int j = 0; j < arr[i].length; j++) {
                System.out.print(arr[i][j] + "\t");
            }
            System.out.println();
        }
    }

    // Method to print jagged array
    public static void printJaggedArray(int[][] arr) {
        for (int i = 0; i < arr.length; i++) {
            System.out.print("Row " + i + ": ");
            for (int j = 0; j < arr[i].length; j++) {
                System.out.print(arr[i][j] + " ");
            }
            System.out.println();
        }
    }

    // Method to add two matrices
    public static int[][] addMatrices(int[][] a, int[][] b) {
        if (a.length != b.length || a[0].length != b[0].length) {
            System.out.println("Matrices must have same dimensions!");
            return null;
        }

        int[][] result = new int[a.length][a[0].length];

        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                result[i][j] = a[i][j] + b[i][j];
            }
        }

        return result;
    }

    // Method to transpose matrix
    public static int[][] transposeMatrix(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        int[][] transpose = new int[cols][rows];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                transpose[j][i] = matrix[i][j];
            }
        }

        return transpose;
    }
}

