import java.util.Arrays;
import java.util.Collections;
import java.util.ArrayList;

public class CommonOperationsDemo {
    public static void main(String[] args) {
        System.out.println("=== Common Array and String Operations ===\n");

        // Array sorting
        System.out.println("=== Array Sorting ===");

        int[] numbers = {5, 2, 8, 1, 9, 3, 7, 4, 6};
        System.out.println("Original array: " + Arrays.toString(numbers));

        Arrays.sort(numbers);
        System.out.println("Sorted array: " + Arrays.toString(numbers));

        // String array sorting
        String[] names = {"John", "Alice", "Bob", "Charlie", "Diana"};
        System.out.println("\nOriginal names: " + Arrays.toString(names));

        Arrays.sort(names);
        System.out.println("Sorted names: " + Arrays.toString(names));

        // Reverse sorting
        Arrays.sort(names, Collections.reverseOrder());
        System.out.println("Reverse sorted names: " + Arrays.toString(names));

        // Array searching
        System.out.println("\n=== Array Searching ===");

        int[] sortedNumbers = {1, 3, 5, 7, 9, 11, 13, 15};
        int searchKey = 7;

        int index = Arrays.binarySearch(sortedNumbers, searchKey);
        System.out.println("Array: " + Arrays.toString(sortedNumbers));
        System.out.println("Index of " + searchKey + ": " + index);

        // Manual search
        int manualIndex = -1;
        for (int i = 0; i < sortedNumbers.length; i++) {
            if (sortedNumbers[i] == searchKey) {
                manualIndex = i;
                break;
            }
        }
        System.out.println("Manual search index: " + manualIndex);

        // Array copying
        System.out.println("\n=== Array Copying ===");

        int[] original = {1, 2, 3, 4, 5};
        int[] copy1 = Arrays.copyOf(original, original.length);
        int[] copy2 = Arrays.copyOf(original, 3);  // First 3 elements
        int[] copy3 = Arrays.copyOfRange(original, 1, 4);  // Elements 1-3

        System.out.println("Original: " + Arrays.toString(original));
        System.out.println("Full copy: " + Arrays.toString(copy1));
        System.out.println("First 3: " + Arrays.toString(copy2));
        System.out.println("Range 1-3: " + Arrays.toString(copy3));

        // Array comparison
        System.out.println("\n=== Array Comparison ===");

        int[] arr1 = {1, 2, 3};
        int[] arr2 = {1, 2, 3};
        int[] arr3 = {1, 2, 4};

        System.out.println("arr1 equals arr2: " + Arrays.equals(arr1, arr2));
        System.out.println("arr1 equals arr3: " + Arrays.equals(arr1, arr3));

        // Array filling
        System.out.println("\n=== Array Filling ===");

        int[] emptyArray = new int[5];
        System.out.println("Before fill: " + Arrays.toString(emptyArray));

        Arrays.fill(emptyArray, 42);
        System.out.println("After fill: " + Arrays.toString(emptyArray));

        // Partial fill
        int[] partialArray = new int[10];
        Arrays.fill(partialArray, 2, 7, 99);  // Fill indices 2-6 with 99
        System.out.println("Partial fill: " + Arrays.toString(partialArray));

        // String operations
        System.out.println("\n=== Common String Operations ===");

        // String joining
        String[] words = {"Hello", "world", "from", "Java"};
        String joined = String.join(" ", words);
        System.out.println("Joined string: " + joined);

        // String formatting
        String name = "Alice";
        int age = 25;
        double salary = 55000.75;

        String formatted = String.format("Name: %s, Age: %d, Salary: $%.2f", name, age, salary);
        System.out.println("Formatted: " + formatted);

        // String repetition (Java 11+)
        String repeated = "Java ".repeat(3);
        System.out.println("Repeated: " + repeated);

        // String blank check (Java 11+)
        String emptyString = "";
        String blankString = "   ";
        String normalString = "Hello";

        System.out.println("\nBlank checks:");
        System.out.println("'" + emptyString + "' is empty: " + emptyString.isEmpty());
        System.out.println("'" + blankString + "' is blank: " + blankString.isBlank());
        System.out.println("'" + normalString + "' is blank: " + normalString.isBlank());

        // Practical examples
        System.out.println("\n=== Practical Examples ===");

        // Remove duplicates from array
        int[] withDuplicates = {1, 2, 2, 3, 4, 4, 4, 5, 5};
        System.out.println("Array with duplicates: " + Arrays.toString(withDuplicates));

        int[] withoutDuplicates = removeDuplicates(withDuplicates);
        System.out.println("Without duplicates: " + Arrays.toString(withoutDuplicates));

        // Count word frequency
        String text = "apple banana apple orange banana apple grape";
        System.out.println("\nText: " + text);
        countWordFrequency(text);

        // Find common elements
        int[] array1 = {1, 2, 3, 4, 5};
        int[] array2 = {3, 4, 5, 6, 7};
        System.out.println("\nArray 1: " + Arrays.toString(array1));
        System.out.println("Array 2: " + Arrays.toString(array2));

        int[] common = findCommonElements(array1, array2);
        System.out.println("Common elements: " + Arrays.toString(common));

        // String palindrome check
        String[] testWords = {"racecar", "hello", "madam", "world", "level"};
        System.out.println("\nPalindrome check:");
        for (String word : testWords) {
            System.out.println(word + ": " + isPalindrome(word));
        }

        // Array statistics
        int[] data = {12, 45, 23, 67, 34, 89, 56, 23, 78, 45};
        System.out.println("\nArray statistics:");
        System.out.println("Data: " + Arrays.toString(data));
        System.out.println("Sum: " + calculateSum(data));
        System.out.println("Average: " + calculateAverage(data));
        System.out.println("Min: " + findMin(data));
        System.out.println("Max: " + findMax(data));
    }

    // Method to remove duplicates from array
    public static int[] removeDuplicates(int[] arr) {
        if (arr.length == 0) return arr;

        Arrays.sort(arr);
        ArrayList<Integer> resultList = new ArrayList<>();
        resultList.add(arr[0]);

        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != arr[i - 1]) {
                resultList.add(arr[i]);
            }
        }

        // Convert back to array
        int[] result = new int[resultList.size()];
        for (int i = 0; i < resultList.size(); i++) {
            result[i] = resultList.get(i);
        }

        return result;
    }

    // Method to count word frequency
    public static void countWordFrequency(String text) {
        String[] words = text.split("\\s+");
        Arrays.sort(words);

        System.out.println("Word frequency:");

        int count = 1;
        for (int i = 1; i < words.length; i++) {
            if (words[i].equals(words[i - 1])) {
                count++;
            } else {
                System.out.println(words[i - 1] + ": " + count);
                count = 1;
            }
        }
        // Print last word
        if (words.length > 0) {
            System.out.println(words[words.length - 1] + ": " + count);
        }
    }

    // Method to find common elements
    public static int[] findCommonElements(int[] arr1, int[] arr2) {
        ArrayList<Integer> commonList = new ArrayList<>();

        for (int num1 : arr1) {
            for (int num2 : arr2) {
                if (num1 == num2 && !commonList.contains(num1)) {
                    commonList.add(num1);
                }
            }
        }

        // Convert to array
        int[] result = new int[commonList.size()];
        for (int i = 0; i < commonList.size(); i++) {
            result[i] = commonList.get(i);
        }

        return result;
    }

    // Method to check palindrome
    public static boolean isPalindrome(String str) {
        String clean = str.replaceAll("[^a-zA-Z0-9]", "").toLowerCase();
        return clean.equals(new StringBuilder(clean).reverse().toString());
    }

    // Statistical methods
    public static int calculateSum(int[] arr) {
        int sum = 0;
        for (int num : arr) {
            sum += num;
        }
        return sum;
    }

    public static double calculateAverage(int[] arr) {
        if (arr.length == 0) return 0.0;
        return (double) calculateSum(arr) / arr.length;
    }

    public static int findMin(int[] arr) {
        if (arr.length == 0) return -1;
        int min = arr[0];
        for (int num : arr) {
            if (num < min) min = num;
        }
        return min;
    }

    public static int findMax(int[] arr) {
        if (arr.length == 0) return -1;
        int max = arr[0];
        for (int num : arr) {
            if (num > max) max = num;
        }
        return max;
    }
}
